from pathlib import Path
import sys,json,time,numpy as np
p=Path(__file__).resolve().parent;sys.path.insert(0,str(p.parent/'rain-corrected-coupled-reference'));from setup import m,r,wave
results={}
for name,seed in [('cold',np.zeros(r.N)),('capped',m.old[r.remaining].copy())]:
 start=time.monotonic();y=seed.copy();history=[];termination='complete'
 for lam in [1.,.1,.01,.001,.0001,.00001,.000001,0.]:
  stage_ok=False
  for step in range(16):
   F=r.residual(y)+lam*(y-seed);nr=float(max(abs(F)/(1+abs(y))))
   if nr<=1e-10:stage_ok=True;break
   D=r.residual(y,True)+lam*r.E;delta,_,rank,_=np.linalg.lstsq(D,-F,rcond=1e-12);accepted=False
   for k in range(8):
    alpha=2.**-k;trial=y+alpha*delta;ft=r.residual(trial)+lam*(trial-seed)
    if ft@ft<=(1-1e-4*alpha)*(F@F):accepted=True;break
   history.append(dict(lam=lam,step=step,augmented_residual=nr,rank=int(rank),alpha=alpha,accepted=accepted))
   if not accepted:termination='line-search-failed';break
   y=trial
  if max(abs(r.residual(y)+lam*(y-seed))/(1+abs(y)))<=1e-10:stage_ok=True
  print(name,lam,stage_ok,flush=True)
  if not stage_ok:
   if termination=='complete':termination='stage-cap'
   break
 x=r.recover(y);natural=float(max(abs(m.residual(x))/(1+abs(x))));grad=m.gradient_primal(x);dense=m.H@x+m.g;agreement=float(max(abs(grad-dense)/(1+np.maximum(abs(grad),abs(dense)))));_,sweep=wave(x);feas=[]
 for b in m.blocks:
  z=x[b['sl']];domain=b['domain'];cap=m.radius(b,x);error=0.
  if domain=='positive':error=max(0,-float(min(z)))
  elif domain=='box':error=max(0,float(max(abs(z)))-cap)/(1+cap)
  elif domain=='ball':error=max(0,float(np.linalg.norm(z))-cap)/(1+cap)
  feas.append(error)
 passed=termination=='complete' and natural<=1e-8 and max(feas)<=1e-8 and agreement<=1e-9 and max(sweep['max_velocity_change'],sweep['max_impulse_change'])<=1e-5
 output=dict(status='reference-pass' if passed else 'reference-failed',termination=termination,seconds=time.monotonic()-start,newton_solves=len(history),natural=natural,feasibility=max(feas),primal=agreement,wave=sweep,history=history);results[name]=output;np.savez(p/(name+'.npz'),impulses=x,velocities=m.vfree+m.M@m.J.T@x);(p/'result.json').write_text(json.dumps(results,indent=2));print(name,json.dumps({k:v for k,v in output.items() if k!='history'}),flush=True)
if not all(v['status']=='reference-pass' for v in results.values()):raise SystemExit(1)

